// RunsServiceHandler is an implementation of the vrooli.test_genie.v1.runs.RunsService service.
type RunsServiceHandler interface {
	// ListRuns enumerates runs for a scenario, newest-first.
	ListRuns(context.Context, *connect.Request[runs.ListRunsRequest]) (*connect.Response[runs.ListRunsResponse], error)
	// GetRun returns a single run record.
	GetRun(context.Context, *connect.Request[runs.GetRunRequest]) (*connect.Response[runs.GetRunResponse], error)
	// DeleteRun removes a run's artifacts and index entry. Pinned runs require force.
	DeleteRun(context.Context, *connect.Request[runs.DeleteRunRequest]) (*connect.Response[runs.DeleteRunResponse], error)
	// PinRun protects a run from retention GC on behalf of an external consumer.
	PinRun(context.Context, *connect.Request[runs.PinRunRequest]) (*connect.Response[runs.PinRunResponse], error)
	// UnpinRun removes a consumer's pin.
	UnpinRun(context.Context, *connect.Request[runs.UnpinRunRequest]) (*connect.Response[runs.UnpinRunResponse], error)
	// CompareRuns classifies the per-phase differences between two runs.
	CompareRuns(context.Context, *connect.Request[runs.CompareRunsRequest]) (*connect.Response[runs.CompareRunsResponse], error)
	// GetPhaseArtifact returns the raw phase-results JSON for a run+phase.
	GetPhaseArtifact(context.Context, *connect.Request[runs.GetPhaseArtifactRequest]) (*connect.Response[runs.GetPhaseArtifactResponse], error)
	// ListRunArtifacts returns the typed, path-free evidence catalog for a run.
	// Kinds are open strings so future provider evidence passes through without
	// a Test Genie or consumer schema change.
	ListRunArtifacts(context.Context, *connect.Request[runs.ListRunArtifactsRequest]) (*connect.Response[runs.ListRunArtifactsResponse], error)
	// GetRunArtifact returns metadata for one opaque run-scoped artifact ID.
	// Bytes are streamed through the access_path advertised on ArtifactRef.
	GetRunArtifact(context.Context, *connect.Request[runs.GetRunArtifactRequest]) (*connect.Response[runs.GetRunArtifactResponse], error)
	// GetRunFindings returns the per-phase maturity standing (Phase Capability
	// Contract) persisted in the run's findings.json, on demand.
	GetRunFindings(context.Context, *connect.Request[runs.GetRunFindingsRequest]) (*connect.Response[runs.GetRunFindingsResponse], error)
	// ListRunVideos enumerates the recorded workflow videos for a run. The bytes
	// themselves are served over a binary REST route (videos stream rather than
	// round-trip through proto); the rel_path here is the handle that route
	// takes. Consumed by git-control-tower's WorkflowReplayService.
	ListRunVideos(context.Context, *connect.Request[runs.ListRunVideosRequest]) (*connect.Response[runs.ListRunVideosResponse], error)
	// ListRunVisuals enumerates the per-page UI visual artifacts (screenshot +
	// optional video) captured by a run under the baseline capture profile. The
	// bytes are served over the same binary REST artifact route (rel_path is the
	// handle); the structured page set + screenshot count is what git-control-tower
	// diffs at the metadata level between two baselines.
	ListRunVisuals(context.Context, *connect.Request[runs.ListRunVisualsRequest]) (*connect.Response[runs.ListRunVisualsResponse], error)
	// CompareRunVisuals returns the per-page pixel-level comparison of two runs'
	// captures by delegating analysis to ui-health. Test Genie owns run
	// orchestration and artifact enumeration only; ui-health owns visual-health
	// analysis and thresholds. Every delta is advisory: a difference is never a
	// verdict here.
	CompareRunVisuals(context.Context, *connect.Request[runs.CompareRunVisualsRequest]) (*connect.Response[runs.CompareRunVisualsResponse], error)
	// FindRun returns the newest completed run matching a shape filter (scenario +
	// optional git_sha / tree_digest / preset / capture_profile / status). It is
	// the reuse primitive: git-control-tower asks "is there already a clean-tree
	// comprehensive+baseline run at this sha?" before starting a new one, so a
	// snapshot-then-diff (or repeated diff) at the same clean tree does not
	// re-run the suite. Read-only.
	FindRun(context.Context, *connect.Request[runs.FindRunRequest]) (*connect.Response[runs.FindRunResponse], error)
	// CheckFreshness reports, per phase, whether some recorded run executed that
	// phase (status passed) against the scenario's CURRENT working-tree digest.
	// Read-only; consumed by git-control-tower's advisory pre-commit step and
	// the `test-genie runs freshness` CLI verb.
	CheckFreshness(context.Context, *connect.Request[runs.CheckFreshnessRequest]) (*connect.Response[runs.CheckFreshnessResponse], error)
	// GetSelfHealth aggregates Test Genie's own observability into one read:
	//
	//	(a) catalog summary (phases, delegated vs native, per-phase provider +
	//	    finding source),
	//	(b) per-provider conformance/adoption against the shared validation
	//	    contract (reachable, contract-valid, identity, maturity.json valid,
	//	    metrics_adopted) — probed LIVE and time-boxed,
	//	(c) the reliability ledger over a recent window (per phase/provider:
	//	    availability %, failure-class + skip-reason histograms, degraded
	//	    counts, duration p50/p95/min/max/avg, worst-scenarios-per-phase) plus
	//	    run-level terminal-outcome counts.
	//
	// Read-only; compute-on-read (no persisted rollups). Consumed by the
	// `test-genie health` CLI verb and the meta-optimization heartbeat.
	GetSelfHealth(context.Context, *connect.Request[runs.GetSelfHealthRequest]) (*connect.Response[runs.GetSelfHealthResponse], error)
	// GetFleetHealth aggregates STORED runs across the whole fleet into a
	// fleet-wide health snapshot: importance/staleness-aware per-scenario rollups
	// (runs, availability, failure rate, issue count, last-run age + outcome),
	// a most-errored ranking, finding-source clustering, and — when a roster is
	// requested — explicit never-tested-in-window coverage gaps. It is
	// compute-on-read over runs that ALREADY executed (the default-OFF background
	// fleet scheduler keeps them fresh); it does NOT launch a fleet run. Every
	// datum is as-of stamped so stale data can never read as fresh. Read-only;
	// consumed by the `test-genie fleet status` CLI verb and meta-optimization.
	GetFleetHealth(context.Context, *connect.Request[runs.GetFleetHealthRequest]) (*connect.Response[runs.GetFleetHealthResponse], error)
	// GetCostReport aggregates measured phase cost over a bounded window. Low
	// reliability samples are reported separately and never blended into totals.
	GetCostReport(context.Context, *connect.Request[runs.GetCostReportRequest]) (*connect.Response[runs.GetCostReportResponse], error)
	// StartRun starts a suite run under a server-lifetime context and returns its
	// run id synchronously (before the suite executes). The run survives client
	// cancellation; observe it via FollowRun/WaitRun/GetRunStatus.
	StartRun(context.Context, *connect.Request[runs.StartRunRequest]) (*connect.Response[runs.StartRunResponse], error)
	// FollowRun streams canonical run events for a run, replaying history so a
	// late or re-attaching follower sees the full sequence. Cancelling the stream
	// detaches the viewer WITHOUT aborting the run.
	FollowRun(context.Context, *connect.Request[runs.FollowRunRequest], *connect.ServerStream[runs.RunEvent]) error
	// WaitRun blocks until the run reaches a terminal state or the timeout
	// elapses, returning the final (or current) live status.
	WaitRun(context.Context, *connect.Request[runs.WaitRunRequest]) (*connect.Response[runs.WaitRunResponse], error)
	// AbortRun cancels a running run and transitions it to aborted.
	AbortRun(context.Context, *connect.Request[runs.AbortRunRequest]) (*connect.Response[runs.AbortRunResponse], error)
	// GetRunStatus returns a point-in-time live snapshot (status, active phase,
	// elapsed, remaining ETA, recommended next-check backoff).
	GetRunStatus(context.Context, *connect.Request[runs.GetRunStatusRequest]) (*connect.Response[runs.RunLiveStatus], error)
}

